class BowlingGame:
    def __init__(self):
        self.rolls = []
        self._frame = 1
        self._frame_rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("A roll cannot score negative points or more than 10")
        if self._complete():
            raise ValueError("Cannot roll after the game is over")

        self.rolls.append(pins)
        self._frame_rolls.append(pins)

        if self._frame < 10:
            if len(self._frame_rolls) == 1:
                if self._frame_rolls[0] == 10:
                    self._advance_frame()
            else:
                if self._frame_rolls[0] + self._frame_rolls[1] > 10:
                    raise ValueError("Two rolls in a frame cannot score more than 10 points")
                self._advance_frame()
        else:
            self._check_tenth_frame()

    def score(self):
        if not self._complete():
            raise ValueError("Cannot score an incomplete game")

        rolls = self.rolls
        total = 0
        i = 0
        for frame in range(10):
            if frame < 9:
                if rolls[i] == 10:
                    total += 10 + rolls[i + 1] + rolls[i + 2]
                    i += 1
                elif rolls[i] + rolls[i + 1] == 10:
                    total += 10 + rolls[i + 2]
                    i += 2
                else:
                    total += rolls[i] + rolls[i + 1]
                    i += 2
            else:
                total += sum(rolls[i:])
        return total

    def _advance_frame(self):
        self._frame += 1
        self._frame_rolls = []

    def _check_tenth_frame(self):
        fr = self._frame_rolls
        if len(fr) == 2:
            if fr[0] < 10:
                # Frame ends after two open rolls; a spare still needs a bonus roll.
                if fr[0] + fr[1] < 10:
                    self._advance_frame()
            elif fr[1] < 10:
                # Strike then a non-strike: the two bonus rolls must not exceed 10.
                if fr[1] + fr[2 - 1] > 10 and len(fr) == 2:
                    pass
        if len(fr) == 3:
            if fr[0] == 10 and fr[1] < 10 and fr[1] + fr[2] > 10:
                raise ValueError("Two rolls in a frame cannot score more than 10 points")
            self._advance_frame()

    def _complete(self):
        if self._frame > 10:
            return True
        if self._frame == 10:
            fr = self._frame_rolls
            if len(fr) >= 3:
                return True
            if len(fr) == 2 and fr[0] + fr[1] < 10:
                return True
        return False

